SELECT u.*
FROM sys_user u

    AND u.is_deleted = 0

    AND (u.status IS NULL OR u.status >= 0)

        AND (u.real_name LIKE #{keyword} OR u.username LIKE #{keyword} OR u.phone LIKE #{keyword})


        AND u.department_id = #{departmentId}


        AND u.position_id = #{positionId}


        AND u.org_level = #{orgLevel}


ORDER BY u.create_time DESC
LIMIT #{pageSize} OFFSET (#{pageNum} - 1) * #{pageSize}

SELECT COUNT(*)
FROM sys_user u

    AND u.is_deleted = 0

    AND (u.status IS NULL OR u.status >= 0)

        AND (u.real_name LIKE #{keyword} OR u.username LIKE #{keyword} OR u.phone LIKE #{keyword})


        AND u.department_id = #{departmentId}


        AND u.position_id = #{positionId}


        AND u.org_level = #{orgLevel}

SELECT role_name FROM sys_role WHERE is_deleted = 0 AND id IN

    #{roleId}

ORDER BY org_level, id

SELECT * FROM sys_user WHERE org_level IN
#{level}
AND org_level > 0 AND status = 1 AND is_deleted = 0 ORDER BY org_level, real_name

SELECT DISTINCT u.* FROM sys_user u INNER JOIN sys_user_role ur ON u.id = ur.user_id INNER JOIN sys_role r ON ur.role_id = r.id WHERE u.org_level IN
#{level}
AND u.status = 1 AND u.is_deleted = 0 AND r.status = 1 AND r.is_deleted = 0 ORDER BY u.org_level ASC, u.id ASC
